            aOrbiterG = RotL64((aOrbiterG * 0x89486175D866ABE7ULL), 23U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterD) + 0xD47EDA8F307C8CEBULL) + aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterF) ^ 0xA81708F7B1ED56F5ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x030F1D43322C58DBULL), 13U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterF) + 0xA8A3DFA87BE6EC0DULL;
