            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0xD2CDEE57A44AECFCULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterE) ^ 0x8F4A1770D9319FAAULL) ^ aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 26U)) & S_SALT1];
