            aCross = (RotL64(aEarthLaneC[((S_BLOCK1 - aIndex + 3860U)) & S_BLOCK1], 29U) ^ RotL64(aEarthLaneD[((S_BLOCK1 - aIndex + 2449U)) & S_BLOCK1], 38U));
            aCross ^= RotL64(aKeyRowReadB[(((2047U - aIndex) + 1908U)) & W_KEY1], 11U);
