            aOrbiterC = ((aWandererF + RotL64(aPrevious, 10U)) + 0x068557D4C25FC06CULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 20U)) & S_SALT1];
            aOrbiterG = (aWandererH + RotL64(aScatter, 47U)) + 0xEBDA85A2EB4AEEC1ULL;
            aOrbiterH = (aWandererI + RotL64(aIngress, 23U)) + 0x3C339F6CE84EA508ULL;
            aOrbiterI = ((aWandererD + RotL64(aCross, 19U)) + RotL64(aCarry, 29U)) + 0xEAD65E69E09830DDULL;
            aOrbiterA = ((aWandererK + RotL64(aIngress, 14U)) + RotL64(aCarry, 3U)) + 0x6DCF2A3388D77A3BULL;
            aOrbiterJ = (aWandererG + RotL64(aPrevious, 43U)) + 0xDF921A0E2EB92272ULL;
            aOrbiterF = ((aWandererC + RotL64(aScatter, 53U)) + RotL64(aCarry, 47U)) + 0x458BD5417D59D9A8ULL;
            aOrbiterB = ((aWandererE + RotL64(aPrevious, 37U)) + 0x082C6EEDCC9587F2ULL) + aTwistOrbiterAssignSaltF[((aIndex + 15U)) & S_SALT1];
            //
            aOrbiterE = (aOrbiterE + aOrbiterC) + 0x97AD0138569CEDD6ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterE) ^ 0x7DF935B2131BE3D0ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x09F9A891F80A9A2FULL), 39U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterH) + 0x4B473141E7D4FC46ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0xBF6A8A44F1D85492ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xB6114249DDCC683FULL), 57U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0x1961623C8A73851CULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterI) ^ 0x49A9BD179EC0DC06ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x4272B85938C82A1DULL), 21U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0x68EB57A0F8576913ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0x32CDCA79B9951B66ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x29C61683D70B111DULL), 47U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0x8C2E0654A2D41C20ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0xCCFA77DB04BDBEF2ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xF7C51E5426520D59ULL), 13U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterG) + 0xA7506F92EE7C7026ULL) + aTwistOrbiterUpdateSaltD[((aIndex + 3U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterA) ^ 0x51DAC2B29F02653BULL) ^ aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xD24E1E72136E151DULL), 29U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterE) + 0x1FACEE5EC131B102ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterH) ^ 0x41BDD18DC67C0A47ULL) ^ aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 19U)) & S_SALT1];
