            aOrbiterE = (aWandererF + RotL64(aCross, 48U)) + 0x5EE4508E51373324ULL;
            aOrbiterB = (aWandererH + RotL64(aPrevious, 57U)) + 0x5A1D9A33E2FCFD5AULL;
            aOrbiterI = (((aWandererJ + RotL64(aScatter, 35U)) + RotL64(aCarry, 57U)) + 0xA4579B314988A135ULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 20U)) & S_SALT1];
            aOrbiterG = ((aWandererE + RotL64(aCross, 19U)) + RotL64(aCarry, 19U)) + 0xB27E26631C6EAAA4ULL;
            aOrbiterA = (aWandererK + RotL64(aIngress, 41U)) + 0x33767095A456591EULL;
            aOrbiterJ = ((aWandererD + RotL64(aPrevious, 5U)) + RotL64(aCarry, 39U)) + 0x1C3F8FC47AC8E38AULL;
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0x764D8215D162AF6AULL;
