            //
            aOrbiterI = ((aOrbiterI + aOrbiterB) + 0xE6E683CEF9774196ULL) + aTwistOrbiterUpdateSaltA[((aIndex + 16U)) & S_SALT1];
            aOrbiterG = ((aOrbiterG ^ aOrbiterI) ^ 0x3F27F75FD2AE42F7ULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 15U)) & S_SALT1];
