            aOrbiterC = (aOrbiterC + aOrbiterB) + 0x6AF71D5364197ED7ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterC) ^ 0x152747812F1B74C4ULL) ^ aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x5F35AC925AA27815ULL), 13U);
