            //
            aIngress = (RotL64(aShadowLaneA[((aIndex + 11327U)) & S_BLOCK1], 29U) ^ RotL64(aPoisonLaneC[((aIndex + 15006U)) & S_BLOCK1], 3U));
            aIngress ^= (RotL64(aWoodLaneD[((aIndex + 11315U)) & S_BLOCK1], 38U) ^ RotL64(aKeyRowReadA[(((2047U - aIndex) + 10431U)) & W_KEY1], 47U));
            aIngress = TwistMix64::DiffuseA((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 11108U)) & S_BLOCK1], 11U) ^ RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 8397U)) & S_BLOCK1], 56U));
            aCross ^= (RotL64(aKeyRowReadB[(((2047U - aIndex) + 10540U)) & W_KEY1], 21U) ^ RotL64(aHeartLaneD[((S_BLOCK1 - aIndex + 16081U)) & S_BLOCK1], 29U));
