            //
            aOrbiterA = (aWandererE + RotL64(aCross, 41U)) + 0x564D5DAC380F3193ULL;
            aOrbiterI = (((aWandererI + RotL64(aIngress, 19U)) + RotL64(aCarry, 39U)) + 0xA8ACC740646336CCULL) + aKeyRotateAOrbiterAssignSaltF[((aIndex + 26U)) & S_SALT1];
            aOrbiterC = ((aWandererD + RotL64(aPrevious, 57U)) + RotL64(aCarry, 57U)) + 0x4BEC35EA8F0D81B2ULL;
            aOrbiterK = (aWandererA + RotL64(aScatter, 35U)) + 0x61C28AE52C5DA85AULL;
            aOrbiterD = ((aWandererF + RotL64(aIngress, 48U)) + 0x3F6490D40EC9799AULL) + aKeyRotateAOrbiterAssignSaltB[(((31U - aIndex) + 24U)) & S_SALT1];
