            //
            aOrbiterI = (aOrbiterI + aOrbiterF) + 0x47A2E459B70B9DACULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterI) ^ 0x0A6A9B53DD6A5A7EULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xAFCED9E23AD253F9ULL), 13U);
