            aOrbiterD = (aOrbiterD + aOrbiterC) + 0x8B95959CBE9AFB63ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterD) ^ 0xCEE479713B271295ULL) ^ aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xAFD4D65D5E124051ULL), 23U);
