            //
            aScatter = (RotL64(aIngress, 36U) + RotL64(aCarry, 21U)) ^ (RotL64(aPrevious, 51U) + RotL64(aCross, 3U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterH = ((aWandererG + RotL64(aCross, 41U)) + RotL64(aCarry, 57U)) + 0xC7165ACAEBB2BAA7ULL;
            aOrbiterC = ((aWandererJ + RotL64(aIngress, 57U)) + 0x9AE3DBCE18350CA3ULL) + aKeyRotateAOrbiterAssignSaltD[((aIndex + 9U)) & S_SALT1];
            aOrbiterF = ((aWandererD + RotL64(aScatter, 29U)) + RotL64(aCarry, 13U)) + 0x45C4154646689AE9ULL;
            aOrbiterA = ((aWandererF + RotL64(aPrevious, 12U)) + RotL64(aCarry, 35U)) + 0x74145197E5355233ULL;
            aOrbiterB = ((aWandererC + RotL64(aCross, 35U)) + 0x43BE262F184A54ACULL) + aKeyRotateAOrbiterAssignSaltA[((aIndex + 29U)) & S_SALT1];
            aOrbiterK = (aWandererE + RotL64(aIngress, 23U)) + 0xC2E5515585BEF66CULL;
            aOrbiterE = (aWandererK + RotL64(aPrevious, 47U)) + 0x9281568D97AACBBEULL;
            //
            aOrbiterH = (aOrbiterH + aOrbiterC) + 0x81DF3ACBDFA399C0ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0xB6B8A451064966E4ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x106969EEA2C187E5ULL), 21U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterB) + 0x5CE173E9CBCE3AAFULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterA) ^ 0xDB617DA70F45089CULL;
            aOrbiterC = RotL64((aOrbiterC * 0xD56B0D8F1E087B6BULL), 57U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterH) + 0x15A5766760E08987ULL) + aKeyRotateAOrbiterUpdateSaltC[((aIndex + 27U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0xA40406540E14383BULL;
            aOrbiterK = RotL64((aOrbiterK * 0xB24A37EEBAD78FCBULL), 47U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterE) + 0x0BB0659AE9A0A2FEULL) + aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterF) ^ 0x3054B352893CCEE6ULL) ^ aKeyRotateAOrbiterUpdateSaltA[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x8BBA3EA036EA7879ULL), 11U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterA) + 0xE63C7F17820246F1ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterE) ^ 0xFCB2D4FC117D729CULL;
            aOrbiterH = RotL64((aOrbiterH * 0xDFC847326846CC95ULL), 29U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0xBCD637672390C4E4ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterC) ^ 0x60EAA66D5B0E69AAULL) ^ aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x323BCD83924BF327ULL), 3U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x707740B5C62127ADULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0xD07CE536C8D88EF2ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x9CB233071B7CA3AFULL), 41U);
            //
            aIngress = RotL64(aOrbiterH, 47U) ^ aOrbiterB;
            aIngress = aIngress + (aOrbiterA ^ RotL64(aOrbiterC, 27U));
            aIngress = aIngress + (aOrbiterK ^ RotL64(aOrbiterF, 13U));
            aIngress = aIngress + RotL64(aOrbiterE, 60U);
