            //
            aWandererK = aWandererK ^ (((RotL64(aPrevious, 35U) + aOrbiterE) + RotL64(aOrbiterH, 47U)) + aKeyRotateAWandererUpdateSaltC[((aIndex + 3U)) & S_SALT1]);
            aWandererE = aWandererE + (((RotL64(aCross, 57U) + aOrbiterE) + RotL64(aOrbiterC, 27U)) + RotL64(aCarry, 43U));
            aWandererD = aWandererD ^ ((RotL64(aScatter, 3U) + aOrbiterH) + RotL64(aOrbiterB, 60U));
            aWandererF = aWandererF + (((RotL64(aIngress, 12U) + aOrbiterB) + RotL64(aOrbiterK, 11U)) + RotL64(aCarry, 11U));
            aWandererG = aWandererG ^ (((RotL64(aScatter, 43U) + RotL64(aOrbiterA, 41U)) + aOrbiterB) + aKeyRotateAWandererUpdateSaltD[(((31U - aIndex) + 24U)) & S_SALT1]);
